def apply(ctx, cur_p):
    if ctx["state"] != "FORCING":
        return 0
    if ctx["force_pos"] >= len(ctx["forced_tokens"]):
        return 0
    forced = ctx["forced_tokens"][ctx["force_pos"]]
    nzw = 0
    for i in range(len(cur_p)):
        if cur_p[i]["id"] != forced:
            cur_p[i]["logit"] = "-inf"
            nzw += 1
    return nzw
